rule "Meraki C2 Port Detection"
when
  has_field("dst_port") AND
  to_string($message.syslog_type) == "meraki" AND
  (
    to_long($message.dst_port) == 4444 OR
    to_long($message.dst_port) == 5555 OR
    to_long($message.dst_port) == 6666 OR
    to_long($message.dst_port) == 1337 OR
    to_long($message.dst_port) == 8443 OR
    to_long($message.dst_port) == 9999
  )
then
  set_field("alert_type", "c2_traffic");
  set_field("rule_level", 12);
  set_field("rule_description", "Meraki: Traffic to suspicious C2/backdoor port");
  set_field("mitre_id", "T1571");
  set_field("alert_severity", "high");
end

rule "Meraki External Database Access"
