rule "Meraki IRC Botnet Detection"
when
  has_field("dst_port") AND
  to_string($message.syslog_type) == "meraki" AND
  (
    to_long($message.dst_port) == 6667 OR
    to_long($message.dst_port) == 6668 OR
    to_long($message.dst_port) == 6669 OR
    to_long($message.dst_port) == 6697 OR
    to_long($message.dst_port) == 7000
  )
then
  set_field("alert_type", "irc_botnet");
  set_field("rule_level", 9);
  set_field("rule_description", "Meraki: IRC traffic detected - possible botnet");
  set_field("mitre_id", "T1071.001");
  set_field("alert_severity", "medium");
end
